SINA_SMART["parasito-hookworm-strongyloides"] = {"lecture":"parasito-hookworm-strongyloides","title":"Hookworms and strongyloidiasis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"parasito-hookworm-strongyloides:e0","text":"Hookworms and Strongyloides infect through the skin (bare feet, mud).","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-hookworm-strongyloides:e1","text":"Ancylostoma duodenale: 2 pairs of hook teeth; blood-sucking in duodenum.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-hookworm-strongyloides:e2","text":"Hookworm → microcytic iron-deficiency anaemia.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-hookworm-strongyloides:e8","text":"Malignant strongyloidiasis on corticosteroids: disseminated, fatal.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-hookworm-strongyloides:e3","text":"Larval lung migration → Löffler syndrome, eosinophilia.","topic":"Hookworms","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-hookworm-strongyloides:e4","text":"Hookworm treatment: albendazole 400 mg single dose + iron and folate.","topic":"Hookworms","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-hookworm-strongyloides:e5","text":"Strongyloides: parthenogenetic female in duodenum.","topic":"Strongyloidiasis: parasite and cycles","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-hookworm-strongyloides:e10","text":"Treatment: ivermectin 200 µg/kg single dose.","topic":"Strongyloidiasis: clinical, diagnosis, treatment","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-hookworm-strongyloides:e6","text":"Autoinfection → persistence 30+ years, saw-tooth eosinophilia.","topic":"Strongyloidiasis: clinical, diagnosis, treatment","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-hookworm-strongyloides:e7","text":"Larva currens: fast-moving sinuous skin cords.","topic":"Strongyloidiasis: clinical, diagnosis, treatment","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-hookworm-strongyloides:e9","text":"Diagnosis: rhabditoid larvae in stool; Baermann method.","topic":"Strongyloidiasis: clinical, diagnosis, treatment","sec":3,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"l4eesz":"a","lkqs30":"a","zqexnz":"a","656f1h":"a","bco9j5":"a","pto1vf":"a","1160pfe":"a","1wb1ccu":"a","4rg1ie":"a","1rf2hhs":"a","1wc3v7j":"a","m2r304":"a","jatuqd":"a","1buxyns":"x"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"parasito-hookworm-strongyloides:e0":{"s":0,"u":["Hookworms and Strongyloides infect through the skin (bare feet, mud).","Two small-intestine nematodes infect humans through the skin when bare feet or hands touch muddy soil contaminated by human faeces : the blood-sucking hookworms ( Ancylostoma duodenale , Necator americanus ), causing iron-deficiency anaemia , and Strongyloides stercoralis (anguillulosis), whose autoinfection cycle lets it persist for decades and explode into fatal malignant strongyloidiasis under corticosteroids."],"dp":[]},"parasito-hookworm-strongyloides:e1":{"s":0,"u":["Ancylostoma duodenale: 2 pairs of hook teeth; blood-sucking in duodenum.","Two small-intestine nematodes infect humans through the skin when bare feet or hands touch muddy soil contaminated by human faeces : the blood-sucking hookworms ( Ancylostoma duodenale , Necator americanus ), causing iron-deficiency anaemia , and Strongyloides stercoralis (anguillulosis), whose autoinfection cycle lets it persist for decades and explode into fatal malignant strongyloidiasis under corticosteroids."],"dp":[]},"parasito-hookworm-strongyloides:e2":{"s":0,"u":["Hookworm → microcytic iron-deficiency anaemia.","Two small-intestine nematodes infect humans through the skin when bare feet or hands touch muddy soil contaminated by human faeces : the blood-sucking hookworms ( Ancylostoma duodenale , Necator americanus ), causing iron-deficiency anaemia , and Strongyloides stercoralis (anguillulosis), whose autoinfection cycle lets it persist for decades and explode into fatal malignant strongyloidiasis under corticosteroids."],"dp":[{"h":"Why hookworm causes anaemia","t":"Each adult hookworm clamps onto the duodenal mucosa with its teeth and sucks blood, moving to new sites and leaving small bleeding points. Hundreds of worms mean a steady daily blood and iron loss, producing microcytic hypochromic anaemia, especially in children and pregnant women with poor iron intake. Treatment must therefore combine a dewormer with iron. Source: the lecture's hookworm definition and treatment slides."}]},"parasito-hookworm-strongyloides:e8":{"s":0,"u":["Malignant strongyloidiasis on corticosteroids: disseminated, fatal.","Two small-intestine nematodes infect humans through the skin when bare feet or hands touch muddy soil contaminated by human faeces : the blood-sucking hookworms ( Ancylostoma duodenale , Necator americanus ), causing iron-deficiency anaemia , and Strongyloides stercoralis (anguillulosis), whose autoinfection cycle lets it persist for decades and explode into fatal malignant strongyloidiasis under corticosteroids."],"dp":[{"h":"Why steroids can make strongyloidiasis fatal","t":"Strongyloides can complete its cycle without leaving the body, and the immune system normally keeps this autoinfection at a low level for decades. Corticosteroids suppress that control, so larvae multiply unchecked, cross the gut wall carrying bacteria and spread to every organ. That is why people from endemic areas with eosinophilia should be tested and treated before long-term steroids. Source: the lecture's malignant anguillulosis slide."}]},"parasito-hookworm-strongyloides:e3":{"s":1,"u":["Larval lung migration → Löffler syndrome, eosinophilia.","Clinical : skin phase (erythema, dermatitis, pruritus; 'miner's itch' after repeated exposure), invasion phase (dry cough, dysphonia, Löffler syndrome , eosinophilia up to 50%), state phase (duodenal signs from blood-sucking adults, microcytic hypochromic iron-deficiency anaemia )."],"dp":[]},"parasito-hookworm-strongyloides:e4":{"s":1,"u":["Hookworm treatment: albendazole 400 mg single dose + iron and folate.","Treatment : albendazole 400 mg single dose , mebendazole 200 mg/day × 3 days, pyrantel; iron and folic acid ."],"dp":[]},"parasito-hookworm-strongyloides:e5":{"s":2,"u":["Strongyloides: parthenogenetic female in duodenum.","S. stercoralis : 1-2 mm; in the duodenum-jejunum only the parthenogenetic female (reproduces without a male); free-living males and females exist in soil."],"dp":[]},"parasito-hookworm-strongyloides:e10":{"s":3,"u":["Treatment: ivermectin 200 µg/kg single dose.","Treatment : albendazole (3 days) or ivermectin 200 µg/kg single dose ."],"dp":[]},"parasito-hookworm-strongyloides:e6":{"s":3,"u":["Autoinfection → persistence 30+ years, saw-tooth eosinophilia.","Orientation : origin, barefoot or farm work, very high eosinophilia (50-60%) in a 'saw-tooth' pattern (repeated autoinfection)."],"dp":[]},"parasito-hookworm-strongyloides:e7":{"s":3,"u":["Larva currens: fast-moving sinuous skin cords.","Clinical : skin phase (pruritus, papular erythema), invasion (dry cough, asthma attacks, Löffler syndrome), state phase (abdominal pain, diarrhoea); larva currens : fast-moving, sinuous, erythematous cords around the belt and abdomen during autoinfection."],"dp":[]},"parasito-hookworm-strongyloides:e9":{"s":3,"u":["Diagnosis: rhabditoid larvae in stool; Baermann method.","Certainty : rhabditoid larvae in stool ; Baermann method (hygro- and thermotropism) and coproculture, essential for light infections."],"dp":[]}},"meta":{"l4eesz":{"a":"recall","vg":"parasito-hookworm-strongyloides:e9/recall/1"},"lkqs30":{"a":"recall","vg":"parasito-hookworm-strongyloides:e1/recall/1"},"zqexnz":{"a":"relationship","vg":"parasito-hookworm-strongyloides:e2/relationship/1"},"656f1h":{"a":"recall","vg":"parasito-hookworm-strongyloides:e3/recall/1"},"bco9j5":{"a":"recall","vg":"parasito-hookworm-strongyloides:e4/recall/1"},"pto1vf":{"a":"recall","vg":"parasito-hookworm-strongyloides:e5/recall/1"},"1160pfe":{"a":"relationship","vg":"parasito-hookworm-strongyloides:e8/relationship/1"},"1wb1ccu":{"a":"recall","vg":"parasito-hookworm-strongyloides:e7/recall/1"},"4rg1ie":{"a":"recall","vg":"parasito-hookworm-strongyloides:e8/recall/1"},"1rf2hhs":{"a":"recall","vg":"parasito-hookworm-strongyloides:e6/recall/1"},"1wc3v7j":{"a":"recall","vg":"parasito-hookworm-strongyloides:e9/recall/2"},"m2r304":{"a":"recall","vg":"parasito-hookworm-strongyloides:e9/recall/3"},"jatuqd":{"a":"recall","vg":"parasito-hookworm-strongyloides:e10/recall/1"}},"explRev":"80182ea0d1ad"};
